insert into public.legal_sources (id, name, issuer, url, description, published_at, last_review_at) values
  ('lfpiorpi-vigente', 'Ley Federal para la Prevención e Identificación de Operaciones con Recursos de Procedencia Ilícita', 'Cámara de Diputados', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/LFPIORPI.pdf', 'Texto vigente de la ley, compilado por la Cámara de Diputados. Incluye la reforma publicada el 16 de julio de 2025.', '2025-07-16'::date, null),
  ('dof-reglamento-2026', 'Reforma al Reglamento de la LFPIORPI', 'DOF', 'https://dof.gob.mx/nota_detalle.php?codigo=5783547&fecha=27/03/2026', 'Decreto por el que se reforma el Reglamento de la LFPIORPI, publicado en el Diario Oficial de la Federación.', '2026-03-27'::date, null),
  ('dof-acuerdo-115-2026', 'Acuerdo 115/2026', 'DOF', 'https://dof.gob.mx/nota_detalle.php?codigo=5795797&fecha=07/08/2026', 'Acuerdo publicado en el Diario Oficial de la Federación el 7 de agosto de 2026, relacionado con las obligaciones en materia de prevención de lavado de dinero.', '2026-08-07'::date, null),
  ('sat-marco-normativo', 'Marco normativo PLD — SAT', 'SAT', 'https://sppld.sat.gob.mx/pld/interiores/marco.html', 'Compilación del marco normativo aplicable a actividades vulnerables publicada por el SAT.', null, null),
  ('sat-umbrales', 'Tabla de umbrales de identificación y aviso — SAT', 'SAT', 'https://sppld.sat.gob.mx/pld/interiores/umbrales.html', 'Tabla oficial del SAT con los umbrales de identificación y de aviso por actividad vulnerable.', null, null),
  ('sppld-portal', 'Portal de Prevención de Lavado de Dinero (SPPLD)', 'SAT', 'https://sppld.sat.gob.mx/', 'Portal donde los sujetos obligados se dan de alta, presentan avisos e informes en ceros.', null, null),
  ('inegi-uma', 'Unidad de Medida y Actualización (UMA) — INEGI', 'INEGI', 'https://www.inegi.org.mx/temas/uma/', 'Valores diario, mensual y anual de la UMA publicados por el INEGI. Entran en vigor el 1 de febrero de cada año.', null, null)
