insert into public.vulnerable_activities (slug, fraction, name, short_name, description, subject_examples, source_ids, provision, verification, last_review_at, editorial_note, status, sort_order) values
  ('juegos-sorteos', 'I', 'Juegos con apuesta, concursos y sorteos', 'Juegos y sorteos', 'Venta de boletos, fichas o cualquier comprobante para participar en juegos con apuesta, concursos o sorteos, así como el pago de premios. Aplica a organismos descentralizados y a quienes operan con permiso de la Secretaría de Gobernación.', array['Casinos y salas de sorteo de números','Operadores de loterías y rifas con permiso','Plataformas de apuestas en línea con permiso vigente','Empresas que organizan concursos con premio en efectivo']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción I', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 0),
  ('tarjetas-credito-servicios', 'II inciso a)', 'Emisión o comercialización de tarjetas de crédito o de servicios', 'Tarjetas de crédito y servicios', 'Emisión o comercialización habitual o profesional de tarjetas de crédito o de servicios por quien no es una entidad financiera. El umbral se mide sobre el gasto mensual acumulado en la cuenta, no por compra.', array['Tiendas departamentales con tarjeta propia','Cadenas con programas de crédito al consumo','Emisores de tarjetas de servicios no bancarias']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción II, inciso a)', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 1),
  ('tarjetas-prepagadas', 'II inciso b)', 'Emisión o comercialización de tarjetas prepagadas', 'Tarjetas prepagadas', 'Emisión, comercialización o abono de recursos en tarjetas prepagadas por quien no es entidad financiera. El umbral de identificación y el de aviso coinciden: toda operación que obliga a identificar también obliga a avisar.', array['Comercializadores de tarjetas de regalo con valor almacenado','Emisores de tarjetas prepagadas de uso general']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción II, inciso b)', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 2),
  ('vales-cupones-monederos', 'II inciso c)', 'Vales, cupones, monederos electrónicos y certificados', 'Vales y monederos', 'Emisión, comercialización o abono de recursos en instrumentos de almacenamiento de valor monetario distintos a las tarjetas: vales, cupones, monederos electrónicos y certificados.', array['Emisores de monederos electrónicos de despensa','Empresas de vales de gasolina o restaurante','Operadores de certificados de valor monetario']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción II, inciso c)', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 3),
  ('cheques-viajero', 'III', 'Emisión y comercialización de cheques de viajero', 'Cheques de viajero', 'Emisión y comercialización habitual o profesional de cheques de viajero por quien no es entidad financiera. Se identifica siempre, sin importar el monto.', array['Casas de cambio no financieras','Agencias de viaje que emiten cheques de viajero']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción III', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 4),
  ('prestamos-creditos', 'IV', 'Préstamos, créditos y mutuos sin ser entidad financiera', 'Préstamos y créditos', 'Ofrecimiento habitual o profesional de operaciones de mutuo, garantía, préstamo o crédito, con o sin garantía, por parte de quien no es una entidad financiera.', array['Casas de empeño','Financieras y prestamistas no regulados por la CNBV','Empresas que otorgan crédito de forma habitual a terceros']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción IV', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 5),
  ('inmuebles-construccion-intermediacion', 'V', 'Construcción, desarrollo e intermediación inmobiliaria', 'Inmobiliaria', 'Prestación habitual o profesional de servicios de construcción o desarrollo de inmuebles, o de intermediación en la transmisión de la propiedad o constitución de derechos sobre inmuebles, cuando hay operaciones de compraventa a favor de un cliente.', array['Inmobiliarias y brókers de bienes raíces','Constructoras que venden directamente al público','Plataformas de intermediación inmobiliaria']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción V', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 6),
  ('desarrollo-inmobiliario', 'V Bis', 'Recepción de recursos destinados a desarrollo inmobiliario', 'Desarrollo inmobiliario', 'Recepción de recursos destinados a un desarrollo inmobiliario cuya finalidad sea su venta o renta. Es la fracción más nueva de la ley: se adicionó por decreto publicado el 16 de julio de 2025 y alcanza esquemas de preventa y coinversión que antes no estaban nombrados.', array['Desarrolladoras que reciben aportaciones para preventa','Vehículos de coinversión inmobiliaria','Promotores que captan recursos de inversionistas para obra']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción V Bis (adicionada DOF 16-07-2025)', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 7),
  ('metales-joyeria', 'VI', 'Metales preciosos, piedras preciosas, joyería y relojes', 'Metales y joyería', 'Comercialización o intermediación habitual o profesional de metales preciosos, piedras preciosas, joyas o relojes. Es objeto de aviso con independencia de la forma de pago.', array['Joyerías','Compraventa de oro y plata','Relojerías de alta gama','Casas de subasta de joyas']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción VI', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 8),
  ('obras-arte', 'VII', 'Subasta y comercialización de obras de arte', 'Obras de arte', 'Subasta o comercialización habitual o profesional de obras de arte cuando la operación alcanza el monto previsto por la ley.', array['Galerías de arte','Casas de subasta','Marchantes y agentes de artistas']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción VII', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 9),
  ('vehiculos', 'VIII', 'Comercialización de vehículos terrestres, marítimos y aéreos', 'Vehículos', 'Distribución y comercialización de todo tipo de vehículos, nuevos o usados, sean terrestres, marítimos o aéreos. Sólo es actividad vulnerable si se realiza de forma habitual o profesional.', array['Agencias automotrices','Lotes de autos usados','Vendedores de embarcaciones y aeronaves']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción VIII', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 10),
  ('blindaje', 'IX', 'Blindaje de vehículos e inmuebles', 'Blindaje', 'Prestación habitual o profesional de servicios de blindaje de vehículos terrestres o de bienes inmuebles.', array['Talleres de blindaje automotriz','Empresas de blindaje arquitectónico']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción IX', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 11),
  ('traslado-custodia-valores', 'X', 'Traslado o custodia de dinero o valores', 'Traslado de valores', 'Prestación habitual o profesional de servicios de traslado o custodia de dinero o valores. Cuando no es posible determinar el monto trasladado o custodiado, procede el aviso en todos los casos. Se exceptúa al Banco de México y a las instituciones de depósito de valores.', array['Empresas de transporte de valores','Servicios de custodia y bóveda']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción X', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 12),
  ('servicios-profesionales', 'XI', 'Servicios profesionales independientes', 'Servicios profesionales', 'Prestación de servicios profesionales de manera independiente, sin relación laboral, cuando se preparan o realizan para un cliente ciertos actos. El aviso no depende de un monto: procede cuando el profesional realiza, en nombre y representación del cliente, la operación financiera relacionada con el acto. La ley preserva el secreto profesional y la garantía de defensa.', array['Contadores públicos independientes','Abogados corporativos y fiscalistas','Consultores que administran recursos de terceros']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XI', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 13),
  ('fe-publica-notarios', 'XII Apartado A', 'Fe pública: notarios públicos', 'Notarios', 'Actos otorgados ante notario público. Cada inciso tiene su propia regla: unos tienen umbral en UMA y otros generan aviso siempre. La reforma de julio de 2025 endureció varios: el umbral de inmuebles bajó de 16,000 a 8,000 UMA, el de fideicomisos de 8,000 a 4,000, y la constitución de personas morales pasó de tener umbral a generar aviso siempre.', array['Notarías públicas']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XII, Apartado A', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 14),
  ('fe-publica-corredores', 'XII Apartado B', 'Fe pública: corredores públicos', 'Corredores públicos', 'Actos en los que interviene un corredor público. Los avalúos tienen umbral en UMA; los actos corporativos, fideicomisos y mutuos mercantiles generan aviso sin importar el monto.', array['Corredurías públicas']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XII, Apartado B', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 15),
  ('fe-publica-servidores-publicos', 'XII Apartado C', 'Fe pública: servidores públicos', 'Servidores públicos con fe pública', 'Servidores públicos a los que la ley confiere la facultad de dar fe pública en el ejercicio de sus atribuciones. La ley enuncia el apartado sin fijar umbrales propios y la tabla del SAT no lo desglosa.', array['Servidores públicos con facultad de dar fe pública conforme al art. 3, fracción VII, LFPIORPI']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XII, Apartado C', 'no_verificado', '2026-08-11'::date, 'La ley enuncia este apartado sin fijar umbrales y la tabla del SAT no lo incluye. No debe publicarse un umbral sin confirmación.', 'publicado', 16),
  ('personas-facilitadoras', 'XII Apartado D', 'Personas facilitadoras públicas y privadas', 'Personas facilitadoras', 'Apartado adicionado por la reforma publicada el 16 de julio de 2025. Alcanza a las personas facilitadoras previstas en la Ley General de Mecanismos Alternativos de Solución de Controversias y remite a los supuestos del Apartado A en los términos que la propia ley señala.', array['Personas facilitadoras públicas de centros de justicia alternativa','Personas facilitadoras privadas certificadas']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XII, Apartado D (adicionado DOF 16-07-2025)', 'no_verificado', '2026-08-11'::date, 'La ley enuncia este apartado sin fijar umbrales y la tabla del SAT no lo incluye. No debe publicarse un umbral sin confirmación.', 'publicado', 17),
  ('donativos', 'XIII', 'Donativos recibidos por asociaciones y sociedades sin fines de lucro', 'Donativos', 'Recepción de donativos por parte de asociaciones y sociedades sin fines de lucro, cuando alcanzan los montos previstos por la ley.', array['Asociaciones civiles','Fundaciones','Instituciones de asistencia privada']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XIII', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 18),
  ('comercio-exterior', 'XIV', 'Comercio exterior: agentes y apoderados aduanales', 'Comercio exterior', 'Prestación de servicios de comercio exterior respecto de mercancías que la ley enumera. Cuatro de los seis incisos generan aviso cualquiera que sea el valor de los bienes; sólo joyería y obras de arte tienen umbral, y se mide por el valor individual del bien, no por el pedimento completo.', array['Agencias aduanales','Apoderados aduanales','Agentes aduanales']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XIV', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 19),
  ('arrendamiento-inmuebles', 'XV', 'Arrendamiento y derechos de uso o goce de inmuebles', 'Arrendamiento', 'Constitución de derechos personales de uso o goce de bienes inmuebles. El umbral se mide sobre el valor mensual, al día en que se realiza el pago o se cumple la obligación. Ojo al matiz: la identificación aplica cuando la renta es superior a 1,605 UMA, y el aviso cuando es igual o superior a 3,210 UMA.', array['Arrendadores de locales comerciales y oficinas','Administradoras de propiedades en renta','Operadores de naves industriales','Propietarios que rentan de forma habitual']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XV', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 20),
  ('activos-virtuales', 'XVI', 'Intercambio de activos virtuales', 'Activos virtuales', 'Ofrecimiento habitual y profesional de intercambio de activos virtuales por sujetos distintos a las entidades financieras, a través de plataformas electrónicas. Alcanza también las operaciones realizadas con ciudadanos mexicanos desde otra jurisdicción. Tiene dos disparadores independientes: el monto de la operación y la contraprestación cobrada por el servicio.', array['Plataformas de intercambio de criptoactivos no reguladas como ITF','Operadores de compraventa de activos virtuales','Cajeros de criptomonedas']::text[], array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XVI', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado', 21)
insert into public.activity_subtypes (activity_slug, slug, name, description) values
  ('servicios-profesionales', 'compraventa-inmuebles', 'Compraventa de inmuebles o cesión de derechos', 'Preparación o realización de la compraventa de bienes inmuebles o la cesión de derechos sobre éstos.'),
  ('servicios-profesionales', 'administracion-recursos', 'Administración y manejo de recursos y activos', 'Administración y manejo de recursos, valores o cualquier otro activo del cliente.'),
  ('servicios-profesionales', 'cuentas-bancarias', 'Manejo de cuentas bancarias, de ahorro o de valores', 'Manejo de cuentas bancarias, de ahorro o de valores del cliente.'),
  ('servicios-profesionales', 'aportaciones-capital', 'Organización de aportaciones de capital', 'Organización de aportaciones de capital o recursos para la constitución, operación y administración de sociedades mercantiles.'),
  ('servicios-profesionales', 'constitucion-personas-morales', 'Constitución y administración de personas morales', 'Constitución, escisión, fusión, operación y administración de personas morales o vehículos corporativos, incluido el fideicomiso y la compraventa de entidades mercantiles.'),
  ('fe-publica-notarios', 'inmuebles', 'Derechos reales sobre inmuebles', 'Transmisión o constitución de derechos reales sobre inmuebles. La base es el valor más alto entre precio pactado, valor catastral, valor comercial o monto garantizado por suerte principal.'),
  ('fe-publica-notarios', 'poderes-irrevocables', 'Poderes irrevocables', 'Otorgamiento de poderes para actos de administración o dominio con carácter irrevocable.'),
  ('fe-publica-notarios', 'constitucion-personas-morales', 'Constitución y modificación de personas morales', 'Constitución de personas morales, modificación patrimonial por aumento o disminución de capital, fusión o escisión, y compraventa de acciones y partes sociales.'),
