  ('comercio-exterior--equipos-tarjetas-pago', 'comercio-exterior', 'equipos-tarjetas-pago', '{"tipo":"siempre"}'::jsonb, '{"tipo":"siempre","nota":"Equipos y materiales para la elaboración de tarjetas de pago. Genera aviso cualquiera que sea el valor de los bienes."}'::jsonb, 'operacion', '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XIV, inciso c)', 'oficial_verificado', '2026-08-11'::date, null, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado'),
  ('comercio-exterior--material-balistico', 'comercio-exterior', 'material-balistico', '{"tipo":"siempre"}'::jsonb, '{"tipo":"siempre","nota":"Materiales de resistencia balística para blindaje de vehículos. Genera aviso cualquiera que sea el valor de los bienes."}'::jsonb, 'operacion', '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XIV, inciso f)', 'oficial_verificado', '2026-08-11'::date, null, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado'),
  ('comercio-exterior--joyas-metales', 'comercio-exterior', 'joyas-metales', '{"tipo":"uma","uma":485,"nota":"El umbral se mide por el valor individual del bien, no por el pedimento completo."}'::jsonb, '{"tipo":"uma","uma":485,"nota":"El umbral se mide por el valor individual del bien, no por el pedimento completo."}'::jsonb, 'operacion', '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XIV, inciso d)', 'oficial_verificado', '2026-08-11'::date, null, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado'),
  ('comercio-exterior--obras-arte', 'comercio-exterior', 'obras-arte', '{"tipo":"uma","uma":4815,"nota":"El umbral se mide por el valor individual del bien."}'::jsonb, '{"tipo":"uma","uma":4815,"nota":"El umbral se mide por el valor individual del bien."}'::jsonb, 'operacion', '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XIV, inciso e)', 'oficial_verificado', '2026-08-11'::date, null, 'Contrastado contra la tabla oficial de umbrales del SAT y el texto vigente de la LFPIORPI (última reforma DOF 16-07-2025).', 'publicado'),
  ('arrendamiento-inmuebles', 'arrendamiento-inmuebles', null, '{"tipo":"uma","uma":1605,"comparador":"mayor","nota":"La ley dice \"superior a\": una renta mensual de exactamente 1,605 UMA no alcanza el umbral de identificación."}'::jsonb, '{"tipo":"uma","uma":3210,"nota":"La ley dice \"igual o superior a\": una renta mensual de exactamente 3,210 UMA sí alcanza el umbral de aviso."}'::jsonb, 'mensual', '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XV', 'oficial_verificado', '2026-08-11'::date, null, 'El valor se mide de forma mensual, al día en que se realiza el pago o se cumple la obligación.', 'publicado'),
  ('activos-virtuales', 'activos-virtuales', null, '{"tipo":"siempre","nota":"Toda operación de intercambio de activos virtuales exige identificar al cliente."}'::jsonb, '{"tipo":"monto_o_comision","umaMonto":210,"umaComision":4,"nota":"Hay dos disparadores independientes: el monto de la operación por cliente (210 UMA) y la contraprestación cobrada por el servicio (4 UMA). Basta con que uno se alcance."}'::jsonb, 'operacion', '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 17, fracción XVI, incisos a) y b)', 'oficial_verificado', '2026-08-11'::date, null, 'Alcanza también operaciones realizadas con ciudadanos mexicanos desde otra jurisdicción.', 'publicado')
