insert into public.cash_restriction_rules (id, slug, name, description, activities, limit_uma, periodicity, discrepancy, valid_from, valid_to, source_ids, provision, verification, last_review_at, editorial_note, status) values
  ('efectivo-inmuebles', 'inmuebles', 'Constitución o transmisión de derechos reales sobre inmuebles', 'Compraventa de inmuebles y demás actos que constituyen o transmiten derechos reales sobre ellos.', array['inmuebles-construccion-intermediacion','desarrollo-inmobiliario','fe-publica-notarios']::text[], 8025, 'operacion', null, '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 32 LFPIORPI', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el art. 32 de la LFPIORPI vigente y la tabla del SAT. Los montos se miden al día en que se realiza el pago o se cumple la obligación.', 'publicado'),
  ('efectivo-vehiculos', 'vehiculos', 'Vehículos nuevos o usados: terrestres, marítimos y aéreos', 'Transmisión de propiedad o constitución de derechos reales sobre vehículos de cualquier tipo, nuevos o usados.', array['vehiculos']::text[], 3210, 'operacion', null, '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 32 LFPIORPI', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el art. 32 de la LFPIORPI vigente y la tabla del SAT. Los montos se miden al día en que se realiza el pago o se cumple la obligación.', 'publicado'),
  ('efectivo-relojes-joyeria-arte', 'relojes-joyeria-arte', 'Relojes, joyería, metales, piedras preciosas y obras de arte', 'Transmisión de propiedad de relojes, joyería, metales preciosos y piedras preciosas, así como de obras de arte. El límite aplica por pieza o por lote.', array['metales-joyeria','obras-arte']::text[], 3210, 'operacion', null, '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 32 LFPIORPI', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el art. 32 de la LFPIORPI vigente y la tabla del SAT. Los montos se miden al día en que se realiza el pago o se cumple la obligación.', 'publicado'),
  ('efectivo-juegos-apuesta', 'juegos-apuesta', 'Boletos de juegos con apuesta y pago de premios', 'Adquisición de boletos para participar en juegos con apuesta, concursos o sorteos, así como la entrega o pago de los premios.', array['juegos-sorteos']::text[], 3210, 'operacion', null, '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 32 LFPIORPI', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el art. 32 de la LFPIORPI vigente y la tabla del SAT. Los montos se miden al día en que se realiza el pago o se cumple la obligación.', 'publicado'),
  ('efectivo-blindaje', 'blindaje', 'Servicios de blindaje', 'Prestación de servicios de blindaje para vehículos o para bienes inmuebles.', array['blindaje']::text[], 3210, 'operacion', null, '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 32 LFPIORPI', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el art. 32 de la LFPIORPI vigente y la tabla del SAT. Los montos se miden al día en que se realiza el pago o se cumple la obligación.', 'publicado'),
  ('efectivo-acciones-partes-sociales', 'acciones-partes-sociales', 'Acciones y partes sociales', 'Transmisión de dominio o constitución de derechos sobre títulos representativos de partes sociales o acciones de personas morales.', array['fe-publica-notarios','fe-publica-corredores','servicios-profesionales']::text[], 3210, 'operacion', null, '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 32 LFPIORPI', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el art. 32 de la LFPIORPI vigente y la tabla del SAT. Los montos se miden al día en que se realiza el pago o se cumple la obligación.', 'publicado'),
  ('efectivo-arrendamiento', 'arrendamiento', 'Arrendamiento de inmuebles, vehículos y bienes blindados', 'Constitución de derechos personales de uso o goce sobre inmuebles, vehículos y bienes blindados. El límite se mide de forma mensual.', array['arrendamiento-inmuebles']::text[], 3210, 'mensual', null, '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 32 LFPIORPI', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el art. 32 de la LFPIORPI vigente y la tabla del SAT. Los montos se miden al día en que se realiza el pago o se cumple la obligación.', 'publicado'),
  ('efectivo-consignacion-pago', 'consignacion-pago', 'Consignación de pago', 'Consignación de pago relacionada con cualquiera de los actos u operaciones anteriores. Fracción adicionada por la reforma publicada el 16 de julio de 2025.', '{}', 3210, 'operacion', '{"descripcion":"Dos fuentes oficiales publican reglas distintas para este supuesto. Mientras la autoridad no lo aclare, la herramienta muestra ambas y no calcula un resultado definitivo.","segunSAT":"La tabla del SAT publica un límite fijo de 3,210 UMA.","segunLey":"El texto de la ley remite al umbral de la fracción con la que se relaciona la consignación: 8,025 UMA si es sobre inmuebles y 3,210 UMA en los demás casos."}'::jsonb, '2025-07-17'::date, null, array['lfpiorpi-vigente','sat-umbrales']::text[], 'Art. 32 LFPIORPI', 'no_verificado', '2026-08-11'::date, 'Existe una contradicción entre la tabla del SAT y el texto de la ley. Requiere revisión editorial antes de publicarse como regla firme.', 'borrador')
insert into public.sanctions (id, article, fraction, scenario, min_uma, max_uma, min_percent, max_percent, severity, notes, valid_from, valid_to, source_ids, provision, verification, last_review_at, editorial_note, status) values
  ('art54-I--53-I', '54', 'I', 'No cumplir con los requerimientos que formule la autoridad competente (art. 53, fracción I).', 200, 2000, null, null, 'media', null, '2025-07-17'::date, null, array['lfpiorpi-vigente']::text[], 'Art. 54, fracción I, en relación con el art. 53, fracción I', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el texto de la LFPIORPI publicado por la Cámara de Diputados (DOF 16-07-2025).', 'publicado'),
  ('art54-I--53-II', '54', 'I', 'No cumplir con las obligaciones de identificar al cliente o usuario, integrar el expediente o conservar la información (art. 53, fracción II).', 200, 2000, null, null, 'alta', null, '2025-07-17'::date, null, array['lfpiorpi-vigente']::text[], 'Art. 54, fracción I, en relación con el art. 53, fracción II', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el texto de la LFPIORPI publicado por la Cámara de Diputados (DOF 16-07-2025).', 'publicado'),
  ('art54-I--53-III', '54', 'I', 'Presentar los avisos de forma extemporánea, incompleta o sin cumplir los requisitos aplicables (art. 53, fracción III).', 200, 2000, null, null, 'alta', 'El texto vigente remite la extemporaneidad mayor a 30 días a la fracción II del art. 54. Existe una posible imprecisión legislativa en esa remisión: el caso concreto requiere análisis jurídico.', '2025-07-17'::date, null, array['lfpiorpi-vigente']::text[], 'Art. 54, fracción I, en relación con el art. 53, fracción III', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el texto de la LFPIORPI publicado por la Cámara de Diputados (DOF 16-07-2025).', 'publicado'),
  ('art54-I--53-IV', '54', 'I', 'Incumplir cualquiera de las demás obligaciones de la ley (art. 53, fracción IV).', 200, 2000, null, null, 'media', null, '2025-07-17'::date, null, array['lfpiorpi-vigente']::text[], 'Art. 54, fracción I, en relación con el art. 53, fracción IV', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el texto de la LFPIORPI publicado por la Cámara de Diputados (DOF 16-07-2025).', 'publicado'),
  ('art54-II--53-V', '54', 'II', 'Incumplir las obligaciones previstas en los arts. 33, 33 Bis y 33 Ter, relativas al uso de la información y al régimen del representante encargado del cumplimiento (art. 53, fracción V).', 2000, 10000, null, null, 'alta', null, '2025-07-17'::date, null, array['lfpiorpi-vigente']::text[], 'Art. 54, fracción II, en relación con el art. 53, fracción V', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el texto de la LFPIORPI publicado por la Cámara de Diputados (DOF 16-07-2025).', 'publicado'),
  ('art54-III--53-VI', '54', 'III', 'Omitir la presentación de los avisos (art. 53, fracción VI).', 10000, 65000, 10, 100, 'critica', 'Se aplica la cantidad que resulte MAYOR entre el rango en UMA y el porcentaje del valor del acto. El porcentaje sólo procede cuando el acto u operación es cuantificable en dinero; si no lo es, queda únicamente el rango en UMA.', '2025-07-17'::date, null, array['lfpiorpi-vigente']::text[], 'Art. 54, fracción III, en relación con el art. 53, fracción VI', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el texto de la LFPIORPI publicado por la Cámara de Diputados (DOF 16-07-2025).', 'publicado'),
  ('art54-III--53-VII', '54', 'III', 'Realizar operaciones liquidadas en efectivo o metales por encima de los límites del art. 32 (art. 53, fracción VII).', 10000, 65000, 10, 100, 'critica', 'Se aplica la cantidad que resulte MAYOR entre el rango en UMA y el porcentaje del valor del acto, cuando éste sea cuantificable en dinero.', '2025-07-17'::date, null, array['lfpiorpi-vigente']::text[], 'Art. 54, fracción III, en relación con el art. 53, fracción VII', 'oficial_verificado', '2026-08-11'::date, 'Contrastado contra el texto de la LFPIORPI publicado por la Cámara de Diputados (DOF 16-07-2025).', 'publicado')
insert into public.obligations (slug, title, summary, category, activities, steps, due_date, recurrence, source_ids, provision, verification, last_review_at, editorial_note, status, sort_order) values
  ('alta-sppld', 'Alta y registro en el portal SPPLD', 'Quien realiza una actividad vulnerable debe darse de alta en el padrón del SAT y habilitar su acceso al portal SPPLD para poder presentar avisos.', 'registro', '{}', '[{"id":"alta-sppld-1","texto":"Contar con e.firma vigente de la persona física o moral.","evidencia":"Constancia de e.firma"},{"id":"alta-sppld-2","texto":"Ingresar al portal SPPLD y seleccionar el alta en actividades vulnerables."},{"id":"alta-sppld-3","texto":"Registrar cada actividad vulnerable que se realiza y su fecha de inicio.","evidencia":"Acuse de alta"},{"id":"alta-sppld-4","texto":"Designar y registrar al representante encargado del cumplimiento.","evidencia":"Acuse de designación"},{"id":"alta-sppld-5","texto":"Resguardar el acuse de alta y los datos de acceso.","evidencia":"Acuse en PDF"}]'::jsonb, null, 'unica', array['lfpiorpi-vigente','sppld-portal']::text[], 'Art. 18, fracción I', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 0),
  ('representante-cumplimiento', 'Designación del representante encargado del cumplimiento', 'Las personas morales deben designar ante la autoridad a un representante encargado del cumplimiento, con facultades suficientes y datos actualizados.', 'gobierno', '{}', '[{"id":"representante-cumplimiento-1","texto":"Elegir a una persona con nivel jerárquico y facultades suficientes."},{"id":"representante-cumplimiento-2","texto":"Formalizar la designación en el órgano de gobierno.","evidencia":"Acta de designación"},{"id":"representante-cumplimiento-3","texto":"Registrar la designación en el portal del SAT.","evidencia":"Acuse de registro"},{"id":"representante-cumplimiento-4","texto":"Actualizar el registro cuando cambie la persona designada."}]'::jsonb, null, 'unica', array['lfpiorpi-vigente']::text[], 'Art. 20', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 1),
  ('identificacion-cliente', 'Identificación del cliente o usuario', 'Antes o al momento de realizar el acto, hay que identificar de forma directa al cliente o usuario y verificar su identidad con documentos válidos.', 'identificacion', '{}', '[{"id":"identificacion-cliente-1","texto":"Recabar los datos generales de la persona física o moral.","evidencia":"Formato de identificación"},{"id":"identificacion-cliente-2","texto":"Verificar la identidad con identificación oficial vigente.","evidencia":"Copia de identificación"},{"id":"identificacion-cliente-3","texto":"Solicitar por escrito si actúa por cuenta propia o de un tercero.","evidencia":"Manifestación firmada"},{"id":"identificacion-cliente-4","texto":"Documentar la actividad u ocupación y el origen de los recursos."}]'::jsonb, null, null, array['lfpiorpi-vigente']::text[], 'Art. 18, fracción I', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 2),
  ('expedientes', 'Integración y actualización de expedientes', 'Cada cliente identificado requiere un expediente único de identificación, actualizado y disponible para la autoridad.', 'expediente', '{}', '[{"id":"expedientes-1","texto":"Crear el expediente único al identificar al cliente."},{"id":"expedientes-2","texto":"Incorporar la documentación soporte de cada operación."},{"id":"expedientes-3","texto":"Revisar y actualizar los datos cuando cambien las circunstancias del cliente."},{"id":"expedientes-4","texto":"Documentar la fecha y responsable de cada actualización.","evidencia":"Bitácora de expediente"}]'::jsonb, null, 'semestral', array['lfpiorpi-vigente']::text[], 'Art. 18, fracción II', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 3),
  ('beneficiario-controlador', 'Identificación del beneficiario controlador', 'Hay que preguntar y documentar quién es la persona física que finalmente se beneficia o controla al cliente, incluso cuando el control es indirecto.', 'identificacion', '{}', '[{"id":"beneficiario-controlador-1","texto":"Solicitar por escrito la manifestación del cliente sobre su beneficiario controlador.","evidencia":"Manifestación firmada"},{"id":"beneficiario-controlador-2","texto":"Reconstruir la cadena de propiedad hasta llegar a personas físicas.","evidencia":"Organigrama corporativo"},{"id":"beneficiario-controlador-3","texto":"Evaluar el control por medios distintos a la propiedad accionaria."},{"id":"beneficiario-controlador-4","texto":"Documentar los casos en que no fue posible determinarlo y las medidas tomadas."}]'::jsonb, null, null, array['lfpiorpi-vigente']::text[], 'Art. 18, fracción III', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 4),
  ('conservacion-diez-anios', 'Conservación de información por diez años', 'La información, documentación y soportes de las operaciones y de la identificación deben conservarse por diez años.', 'conservacion', '{}', '[{"id":"conservacion-diez-anios-1","texto":"Definir el repositorio y el formato de conservación."},{"id":"conservacion-diez-anios-2","texto":"Garantizar respaldo y recuperación de la información.","evidencia":"Política de respaldo"},{"id":"conservacion-diez-anios-3","texto":"Controlar accesos y registrar consultas.","evidencia":"Bitácora de accesos"},{"id":"conservacion-diez-anios-4","texto":"Documentar el criterio de cómputo del plazo de diez años."}]'::jsonb, null, null, array['lfpiorpi-vigente']::text[], 'Art. 18, fracción IV', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 5),
  ('avisos', 'Presentación de avisos a más tardar el día 17', 'Los avisos por operaciones que alcanzan el umbral se presentan a más tardar el día 17 del mes siguiente a aquel en que ocurrió la operación.', 'avisos', '{}', '[{"id":"avisos-1","texto":"Identificar las operaciones del mes que alcanzan el umbral de aviso."},{"id":"avisos-2","texto":"Preparar el archivo con el formato oficial vigente."},{"id":"avisos-3","texto":"Revisar y aprobar internamente antes de enviar.","evidencia":"Registro de aprobación"},{"id":"avisos-4","texto":"Enviar por el portal SPPLD y resguardar el acuse.","evidencia":"Acuse de recepción"}]'::jsonb, null, 'mensual', array['lfpiorpi-vigente','sppld-portal']::text[], 'Art. 23', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 6),
  ('informes-en-ceros', 'Informes en ceros', 'Cuando en el periodo no hubo operaciones que alcanzaran el umbral de aviso, de todas formas debe presentarse el informe correspondiente.', 'avisos', '{}', '[{"id":"informes-en-ceros-1","texto":"Confirmar que en el periodo no hubo operaciones que alcanzaran el umbral."},{"id":"informes-en-ceros-2","texto":"Presentar el informe en ceros dentro del mismo plazo del día 17."},{"id":"informes-en-ceros-3","texto":"Resguardar el acuse.","evidencia":"Acuse de recepción"}]'::jsonb, null, 'mensual', array['lfpiorpi-vigente','sppld-portal']::text[], 'Art. 23', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 7),
  ('operaciones-inusuales', 'Avisos de operaciones inusuales en 24 horas', 'Cuando se detecta una operación inusual o preocupante, el aviso corre en un plazo mucho más corto que el ordinario. Incluye supuestos de operaciones intentadas.', 'avisos', '{}', '[{"id":"operaciones-inusuales-1","texto":"Documentar la alerta y el análisis que la originó.","evidencia":"Expediente del caso"},{"id":"operaciones-inusuales-2","texto":"Escalar al representante encargado del cumplimiento."},{"id":"operaciones-inusuales-3","texto":"Presentar el aviso dentro del plazo de 24 horas cuando proceda.","evidencia":"Acuse"},{"id":"operaciones-inusuales-4","texto":"Registrar la decisión aunque se concluya que no procede el aviso."}]'::jsonb, null, null, array['lfpiorpi-vigente']::text[], 'Art. 17 y disposiciones de carácter general', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 8),
  ('enfoque-basado-riesgos', 'Metodología de enfoque basado en riesgos', 'Se debe contar con una metodología documentada que evalúe los riesgos del negocio y clasifique a los clientes en función de ellos.', 'riesgos', '{}', '[{"id":"enfoque-basado-riesgos-1","texto":"Identificar factores de riesgo: operación, cliente, geografía y canal de entrega."},{"id":"enfoque-basado-riesgos-2","texto":"Asignar ponderaciones y documentar el criterio.","evidencia":"Documento de metodología"},{"id":"enfoque-basado-riesgos-3","texto":"Definir mitigantes y su efecto en el puntaje."},{"id":"enfoque-basado-riesgos-4","texto":"Usar información de los últimos doce meses o proyecciones si no hay historial."},{"id":"enfoque-basado-riesgos-5","texto":"Revisar al menos una vez al año o cuando surjan nuevos riesgos.","evidencia":"Acta de revisión"}]'::jsonb, null, 'anual', array['lfpiorpi-vigente','dof-reglamento-2026','dof-acuerdo-115-2026']::text[], 'Reglamento y disposiciones de carácter general', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 9),
  ('clasificacion-clientes', 'Clasificación de clientes por nivel de riesgo', 'Cada cliente debe quedar clasificado en riesgo bajo, medio o alto, y la clasificación debe revisarse periódicamente.', 'riesgos', '{}', '[{"id":"clasificacion-clientes-1","texto":"Aplicar la metodología a cada cliente al darlo de alta."},{"id":"clasificacion-clientes-2","texto":"Registrar el nivel resultante y su justificación.","evidencia":"Ficha de riesgo"},{"id":"clasificacion-clientes-3","texto":"Aplicar debida diligencia reforzada a los de riesgo alto."},{"id":"clasificacion-clientes-4","texto":"Revisar la clasificación al menos cada seis meses.","evidencia":"Bitácora de revisión"}]'::jsonb, null, 'semestral', array['lfpiorpi-vigente']::text[], 'Reglamento y disposiciones de carácter general', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 10),
  ('perfil-transaccional', 'Perfil transaccional y su revisión semestral', 'Hay que construir un perfil esperado de operación para cada cliente y compararlo contra su comportamiento real de forma periódica.', 'riesgos', '{}', '[{"id":"perfil-transaccional-1","texto":"Definir el perfil esperado con base en la actividad declarada del cliente."},{"id":"perfil-transaccional-2","texto":"Comparar el comportamiento real contra el perfil."},{"id":"perfil-transaccional-3","texto":"Documentar y analizar las desviaciones relevantes.","evidencia":"Reporte de desviaciones"},{"id":"perfil-transaccional-4","texto":"Actualizar el perfil al menos cada seis meses."}]'::jsonb, null, 'semestral', array['lfpiorpi-vigente']::text[], 'Disposiciones de carácter general', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 11),
  ('personas-politicamente-expuestas', 'Personas políticamente expuestas (PEP)', 'Se debe identificar si el cliente, su beneficiario controlador o sus familiares cercanos son PEP y aplicar medidas reforzadas cuando así sea.', 'riesgos', '{}', '[{"id":"personas-politicamente-expuestas-1","texto":"Consultar al cliente y verificar contra fuentes de PEP."},{"id":"personas-politicamente-expuestas-2","texto":"Extender la revisión a familiares y asociados cercanos."},{"id":"personas-politicamente-expuestas-3","texto":"Obtener aprobación de un nivel jerárquico superior para iniciar o continuar la relación.","evidencia":"Aprobación documentada"},{"id":"personas-politicamente-expuestas-4","texto":"Aplicar monitoreo reforzado y revisión más frecuente."}]'::jsonb, null, null, array['lfpiorpi-vigente']::text[], 'Disposiciones de carácter general', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 12),
  ('manual-cumplimiento', 'Manual de políticas y procedimientos internos', 'El manual documenta cómo la organización cumple: identificación, expedientes, avisos, riesgos, capacitación, auditoría y conservación.', 'gobierno', '{}', '[{"id":"manual-cumplimiento-1","texto":"Redactar las políticas de identificación, expediente y conservación."},{"id":"manual-cumplimiento-2","texto":"Documentar los criterios de detección y escalamiento de operaciones inusuales."},{"id":"manual-cumplimiento-3","texto":"Aprobar el manual en el órgano de gobierno.","evidencia":"Acta de aprobación"},{"id":"manual-cumplimiento-4","texto":"Versionar el manual y conservar las versiones anteriores.","evidencia":"Control de versiones"}]'::jsonb, null, 'anual', array['lfpiorpi-vigente']::text[], 'Reglamento y disposiciones de carácter general', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 13),
  ('mecanismos-automatizados', 'Mecanismos automatizados', 'La normativa exige contar con sistemas que apoyen la detección de umbrales, la acumulación, las alertas y la trazabilidad de las decisiones.', 'tecnologia', '{}', '[{"id":"mecanismos-automatizados-1","texto":"Concentrar las operaciones en una base única y consultable."},{"id":"mecanismos-automatizados-2","texto":"Configurar reglas de umbral y acumulación por actividad."},{"id":"mecanismos-automatizados-3","texto":"Generar alertas y dejar registro de su resolución.","evidencia":"Bitácora de alertas"},{"id":"mecanismos-automatizados-4","texto":"Conservar el historial de cambios de reglas con autor, fecha y motivo.","evidencia":"Control de versiones de reglas"}]'::jsonb, null, null, array['lfpiorpi-vigente','dof-reglamento-2026','dof-acuerdo-115-2026']::text[], 'Reglamento y disposiciones de carácter general', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 14),
  ('capacitacion', 'Capacitación anual del personal', 'El personal involucrado debe recibir capacitación al menos una vez al año, con evidencia de asistencia y evaluación.', 'capacitacion', '{}', '[{"id":"capacitacion-1","texto":"Definir el programa anual y el personal alcanzado."},{"id":"capacitacion-2","texto":"Impartir la capacitación y registrar asistencia.","evidencia":"Lista de asistencia"},{"id":"capacitacion-3","texto":"Evaluar la comprensión de los participantes.","evidencia":"Resultados de evaluación"},{"id":"capacitacion-4","texto":"Conservar constancias por el plazo aplicable.","evidencia":"Constancias"}]'::jsonb, null, 'anual', array['lfpiorpi-vigente']::text[], 'Reglamento y disposiciones de carácter general', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 15),
  ('investigacion-personal', 'Selección e investigación de personal', 'Debe existir un procedimiento documentado para investigar los antecedentes del personal que participa en las funciones de cumplimiento.', 'gobierno', '{}', '[{"id":"investigacion-personal-1","texto":"Definir el alcance de la investigación por puesto."},{"id":"investigacion-personal-2","texto":"Documentar la verificación de antecedentes y referencias.","evidencia":"Expediente de personal"},{"id":"investigacion-personal-3","texto":"Registrar la decisión de contratación y sus fundamentos."}]'::jsonb, null, null, array['lfpiorpi-vigente']::text[], 'Reglamento y disposiciones de carácter general', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 16),
  ('auditoria-anual', 'Auditoría anual de cumplimiento', 'El programa de cumplimiento debe someterse a una auditoría con periodicidad anual, que genera hallazgos y un plan de remediación.', 'auditoria', '{}', '[{"id":"auditoria-anual-1","texto":"Seleccionar al auditor y verificar que cumpla los requisitos aplicables."},{"id":"auditoria-anual-2","texto":"Definir el alcance y el plan de trabajo.","evidencia":"Carta de alcance"},{"id":"auditoria-anual-3","texto":"Documentar hallazgos con su severidad.","evidencia":"Informe de auditoría"},{"id":"auditoria-anual-4","texto":"Establecer plan de remediación con responsables y fechas.","evidencia":"Plan de remediación"},{"id":"auditoria-anual-5","texto":"Dar seguimiento al cierre de cada hallazgo."}]'::jsonb, null, 'anual', array['lfpiorpi-vigente','dof-reglamento-2026','dof-acuerdo-115-2026']::text[], 'Reglamento y disposiciones de carácter general', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 17),
  ('dictamen', 'Dictamen y seguimiento de observaciones', 'El resultado de la auditoría se formaliza en un dictamen que se presenta ante la autoridad en el plazo aplicable.', 'auditoria', '{}', '[{"id":"dictamen-1","texto":"Integrar el dictamen con base en el informe de auditoría."},{"id":"dictamen-2","texto":"Aprobarlo en el órgano de gobierno.","evidencia":"Acta de aprobación"},{"id":"dictamen-3","texto":"Presentarlo en el plazo aplicable y resguardar el acuse.","evidencia":"Acuse"},{"id":"dictamen-4","texto":"Dar seguimiento a las observaciones hasta su cierre."}]'::jsonb, null, 'anual', array['lfpiorpi-vigente']::text[], 'Disposiciones de carácter general', 'fuente_secundaria', '2026-08-11'::date, 'Pendiente de contraste literal contra el texto vigente y el Acuerdo 115/2026.', 'revisado', 18)
insert into public.deadlines (id, due_date, end_date, title, description, obligations, officially_confirmed, source_ids, provision, verification, last_review_at, editorial_note, status) values
  ('vigencia-general', '2026-11-30'::date, null, 'Entrada en vigor del Acuerdo 115/2026', 'Fecha en que entran en vigor las reglas del Acuerdo 115/2026, que modifica las Reglas de Carácter General en materia de la LFPIORPI. A partir de aquí corren los plazos escalonados del resto del calendario.', array['manual-cumplimiento','enfoque-basado-riesgos']::text[], true, array['dof-acuerdo-115-2026']::text[], 'Artículo Primero Transitorio, Acuerdo 115/2026', 'oficial_verificado', '2026-08-11'::date, 'Fecha tomada de los artículos transitorios del Acuerdo 115/2026 publicado en el DOF.', 'publicado'),
  ('capacitacion-2027', '2027-01-01'::date, '2027-12-31'::date, 'Primer periodo anual de capacitación', 'El ejercicio 2027 completo constituye el primer periodo anual de capacitación bajo las nuevas reglas. La evidencia de asistencia y evaluación debe quedar documentada dentro de este periodo.', array['capacitacion']::text[], true, array['dof-acuerdo-115-2026']::text[], 'Artículos Transitorios, Acuerdo 115/2026', 'oficial_verificado', '2026-08-11'::date, 'Fecha tomada de los artículos transitorios del Acuerdo 115/2026 publicado en el DOF.', 'publicado'),
  ('ebr-manual-2027', '2027-03-01'::date, null, 'Metodología de riesgos, manual y expedientes', 'A partir de esta fecha la metodología de enfoque basado en riesgos debe estar disponible para la autoridad, alimentada con datos del año anterior, y el manual debe incorporarla. También aplican en esta fecha las reglas sobre clasificación de clientes, expedientes, beneficiario controlador y los procedimientos de selección de personal para nuevas contrataciones.', array['enfoque-basado-riesgos','manual-cumplimiento','clasificacion-clientes','expedientes','beneficiario-controlador','investigacion-personal']::text[], true, array['dof-acuerdo-115-2026']::text[], 'Artículos Transitorios, Acuerdo 115/2026', 'oficial_verificado', '2026-08-11'::date, 'Fecha tomada de los artículos transitorios del Acuerdo 115/2026 publicado en el DOF.', 'publicado'),
  ('psav-actualizacion', '2027-05-30'::date, null, 'Actualización de proveedores de servicios de activos virtuales', 'Plazo de seis meses contados desde la entrada en vigor. El texto oficial fija el plazo en meses, no una fecha calendario: esta fecha es un cálculo orientativo y debe confirmarse contra el transitorio aplicable.', '{}', false, array['dof-acuerdo-115-2026']::text[], 'Artículos Transitorios, Acuerdo 115/2026 (plazo en meses)', 'no_verificado', '2026-08-11'::date, 'Fecha estimada a partir de un plazo en meses. No hay una fecha calendario en el texto oficial.', 'revisado'),
  ('mecanismos-automatizados-2027', '2027-06-01'::date, null, 'Mecanismos automatizados en operación', 'Fecha a partir de la cual los mecanismos automatizados deben estar operando: detección de umbrales, acumulación, alertas y trazabilidad de las decisiones.', array['mecanismos-automatizados']::text[], true, array['dof-acuerdo-115-2026']::text[], 'Artículos Transitorios, Acuerdo 115/2026', 'oficial_verificado', '2026-08-11'::date, 'Fecha tomada de los artículos transitorios del Acuerdo 115/2026 publicado en el DOF.', 'publicado'),
  ('notificaciones-electronicas', '2027-07-30'::date, null, 'Notificaciones electrónicas', 'Plazo de ocho meses desde la entrada en vigor para el esquema de notificaciones electrónicas. Fecha calculada a partir de un plazo en meses; requiere confirmación.', '{}', false, array['dof-acuerdo-115-2026']::text[], 'Artículos Transitorios, Acuerdo 115/2026 (plazo en meses)', 'no_verificado', '2026-08-11'::date, 'Fecha estimada a partir de un plazo en meses. No hay una fecha calendario en el texto oficial.', 'revisado'),
  ('consulta-pep-2', '2027-08-30'::date, null, 'Disponibilidad prevista de Consulta PEP 2.0', 'La herramienta Consulta PEP 2.0 está prevista en el art. 23 Quáter 1 y se ofrecerá en el portal de la UIF, con acceso mediante la e.firma registrada en el alta. El plazo oficial es de nueve meses desde la entrada en vigor; esta fecha es un cálculo orientativo y no una fecha publicada.', array['personas-politicamente-expuestas']::text[], false, array['dof-acuerdo-115-2026']::text[], 'Art. 23 Quáter 1 y Transitorios, Acuerdo 115/2026 (plazo en meses)', 'no_verificado', '2026-08-11'::date, 'Fecha estimada a partir de un plazo en meses. No hay una fecha calendario en el texto oficial.', 'revisado'),
  ('auditoria-2028', '2028-01-01'::date, '2028-12-31'::date, 'Primer periodo de auditoría anual', 'El ejercicio 2028 completo constituye el primer periodo sujeto a auditoría anual. La auditoría puede ser interna cuando el riesgo de la organización es bajo o medio; es obligatoriamente externa cuando el riesgo es alto.', array['auditoria-anual']::text[], true, array['dof-acuerdo-115-2026']::text[], 'Artículos Transitorios, Acuerdo 115/2026', 'oficial_verificado', '2026-08-11'::date, 'Fecha tomada de los artículos transitorios del Acuerdo 115/2026 publicado en el DOF.', 'publicado'),
  ('dictamen-2029', '2029-03-30'::date, null, 'Entrega del primer dictamen (ejercicio 2028)', 'El primer dictamen, correspondiente al ejercicio 2028, se entrega a más tardar el último día hábil de marzo de 2029. La norma habla de "último día hábil": la fecha exacta depende del calendario oficial de días inhábiles de ese año y debe confirmarse antes de usarla como fecha límite operativa.', array['dictamen']::text[], true, array['dof-acuerdo-115-2026']::text[], 'Artículos Transitorios, Acuerdo 115/2026', 'oficial_verificado', '2026-08-11'::date, 'Fecha tomada de los artículos transitorios del Acuerdo 115/2026 publicado en el DOF.', 'publicado')
