-- ============================================================================
-- seed.sql — GENERADO AUTOMÁTICAMENTE. No lo edites a mano.
--
-- Fuente: packages/rules-engine/src/datos/*.ts
-- Regenerar: ver la sección "Regenerar seed.sql" de supabase/README.md
-- Versión del corpus legal: 2026.08.11
--
-- Es idempotente: se puede correr las veces que haga falta. Cada ejecución
-- deja rastro en content_revisions gracias a los triggers de la migración 0010,
-- que es exactamente lo que se quiere: sembrar también es un cambio.
-- ============================================================================

-- El motivo del cambio viaja en una variable de sesión y lo recoge el trigger
-- de versionado.
select set_config('app.motivo_cambio', 'Carga de datos semilla desde el motor jurídico 2026.08.11', false);

on conflict (version) do update set
  published_at = excluded.published_at,
  valid_from = excluded.valid_from,
  valid_to = excluded.valid_to,
  description = excluded.description,
  is_current = excluded.is_current;

on conflict (id) do update set
  name = excluded.name,
  issuer = excluded.issuer,
  url = excluded.url,
  description = excluded.description,
  published_at = excluded.published_at,
  last_review_at = excluded.last_review_at;

on conflict (year) do update set
  daily_cents = excluded.daily_cents,
  valid_from = excluded.valid_from,
  valid_to = excluded.valid_to,
  source_ids = excluded.source_ids,
  provision = excluded.provision,
  verification = excluded.verification,
  last_review_at = excluded.last_review_at,
  editorial_note = excluded.editorial_note,
  status = excluded.status;

on conflict (slug) do update set
  fraction = excluded.fraction,
  name = excluded.name,
  short_name = excluded.short_name,
  description = excluded.description,
  subject_examples = excluded.subject_examples,
  source_ids = excluded.source_ids,
  provision = excluded.provision,
  verification = excluded.verification,
  last_review_at = excluded.last_review_at,
  editorial_note = excluded.editorial_note,
  status = excluded.status,
  sort_order = excluded.sort_order;

on conflict (activity_slug, slug) do update set
  name = excluded.name,
  description = excluded.description;

on conflict (id) do update set
  activity_slug = excluded.activity_slug,
  subtype = excluded.subtype,
  identification_spec = excluded.identification_spec,
  notice_spec = excluded.notice_spec,
  periodicity = excluded.periodicity,
  valid_from = excluded.valid_from,
  valid_to = excluded.valid_to,
  source_ids = excluded.source_ids,
  provision = excluded.provision,
  verification = excluded.verification,
  last_review_at = excluded.last_review_at,
  reviewed_by = excluded.reviewed_by,
  editorial_note = excluded.editorial_note,
  status = excluded.status;

-- Reglas de acumulación del corpus (organization_id nulo = aplican a todas).
on conflict do nothing;

on conflict (id) do update set
  slug = excluded.slug,
  name = excluded.name,
  description = excluded.description,
  activities = excluded.activities,
  limit_uma = excluded.limit_uma,
  periodicity = excluded.periodicity,
  discrepancy = excluded.discrepancy,
  valid_from = excluded.valid_from,
  valid_to = excluded.valid_to,
  source_ids = excluded.source_ids,
  provision = excluded.provision,
  verification = excluded.verification,
  last_review_at = excluded.last_review_at,
  editorial_note = excluded.editorial_note,
  status = excluded.status;

on conflict (id) do update set
  article = excluded.article,
  fraction = excluded.fraction,
  scenario = excluded.scenario,
  min_uma = excluded.min_uma,
  max_uma = excluded.max_uma,
  min_percent = excluded.min_percent,
  max_percent = excluded.max_percent,
  severity = excluded.severity,
  notes = excluded.notes,
  valid_from = excluded.valid_from,
  valid_to = excluded.valid_to,
  source_ids = excluded.source_ids,
  provision = excluded.provision,
  verification = excluded.verification,
  last_review_at = excluded.last_review_at,
  editorial_note = excluded.editorial_note,
  status = excluded.status;

on conflict (slug) do update set
  title = excluded.title,
  summary = excluded.summary,
  category = excluded.category,
  activities = excluded.activities,
  steps = excluded.steps,
  due_date = excluded.due_date,
  recurrence = excluded.recurrence,
  source_ids = excluded.source_ids,
  provision = excluded.provision,
  verification = excluded.verification,
  last_review_at = excluded.last_review_at,
  editorial_note = excluded.editorial_note,
  status = excluded.status,
  sort_order = excluded.sort_order;

on conflict (id) do update set
  due_date = excluded.due_date,
  end_date = excluded.end_date,
  title = excluded.title,
  description = excluded.description,
  obligations = excluded.obligations,
  officially_confirmed = excluded.officially_confirmed,
  source_ids = excluded.source_ids,
  provision = excluded.provision,
  verification = excluded.verification,
  last_review_at = excluded.last_review_at,
  editorial_note = excluded.editorial_note,
  status = excluded.status;

on conflict (slug) do update set
  name = excluded.name,
  description = excluded.description,
  sort_order = excluded.sort_order;

on conflict (key) do nothing;

select set_config('app.motivo_cambio', '', false);
